from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak
out='output/pdf/D5_Configuration_Completion_Rules.pdf'
navy=colors.HexColor('#172f59'); blue=colors.HexColor('#3568b8'); green=colors.HexColor('#267044'); amber=colors.HexColor('#8d5d00'); red=colors.HexColor('#b4232b'); pale=colors.HexColor('#f3f6fc'); line=colors.HexColor('#cfdaf0')
styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name='TitleX',parent=styles['Title'],fontName='Helvetica-Bold',fontSize=20,leading=24,textColor=navy,spaceAfter=5)); styles.add(ParagraphStyle(name='Sub',fontName='Helvetica',fontSize=9.5,leading=14,textColor=colors.HexColor('#526787'))); styles.add(ParagraphStyle(name='H2X',parent=styles['Heading2'],fontName='Helvetica-Bold',fontSize=13,leading=16,textColor=navy,spaceBefore=10,spaceAfter=7)); styles.add(ParagraphStyle(name='Cell',fontName='Helvetica',fontSize=8.3,leading=11,textColor=navy)); styles.add(ParagraphStyle(name='CellC',parent=styles['Cell'],fontName='Helvetica-Bold',alignment=TA_CENTER)); styles.add(ParagraphStyle(name='Head',parent=styles['CellC'],textColor=colors.white));
P=lambda x,s='Cell':Paragraph(x,styles[s]);
def badge(t,c): return Table([[P(t,'CellC')]],colWidths=[34*mm],style=TableStyle([('BACKGROUND',(0,0),(-1,-1),colors.Color(c.red,c.green,c.blue,alpha=.12)),('TEXTCOLOR',(0,0),(-1,-1),c),('BOX',(0,0),(-1,-1),.7,c),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
doc=SimpleDocTemplate(out,pagesize=A4,rightMargin=15*mm,leftMargin=15*mm,topMargin=14*mm,bottomMargin=14*mm,title='D5 Configuration Completion Rules')
story=[P('D5. CABIN & EQUIPMENT','TitleX'),P('AHM565 Sheet D5 - Configuration Completion Rules','Sub'),Spacer(1,5*mm),P('Implementation scope','H2X'),P('All three D5 sections are supported and stored against the selected carrier, aircraft type and series/sub-type. Lateral balance and lateral-arm data are outside the current scope and do not affect completion.'),Spacer(1,3*mm)]
head=[P('Section','Head'),P('CONFIGURED','Head'),P('PARTIALLY CONFIGURED','Head'),P('INCOMPLETE','Head')]
rows=[head,[P('1. Cabin Definitions'),P('At least one row; every saved row is complete and valid.'),P('One or more rows exist, but at least one row is incomplete or invalid.'),P('No rows exist.')],[P('2. Flight Deck Locations'),P('At least one row; every saved row is complete and valid.'),P('One or more rows exist, but at least one row is incomplete or invalid.'),P('No rows exist.')],[P('3. Cabin Crew Locations'),P('At least one row; every saved row is complete and valid.'),P('One or more rows exist, but at least one row is incomplete or invalid.'),P('No rows exist.')],[P('D5 Page'),P('All three sections are CONFIGURED.'),P('The three supported sections have mixed states.'),P('All three sections are INCOMPLETE.')]]
t=Table(rows,colWidths=[35*mm,48*mm,52*mm,45*mm],repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),navy),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.6,line),('VALIGN',(0,0),(-1,-1),'TOP'),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('BACKGROUND',(1,1),(1,-1),colors.HexColor('#e7f5eb')),('BACKGROUND',(2,1),(2,-1),colors.HexColor('#fff4d6')),('BACKGROUND',(3,1),(3,-1),colors.HexColor('#fde8ea'))]));story += [t,Spacer(1,4*mm),P('Required fields','H2X')]
fields=[[P('Section','Head'),P('Required row data','Head'),P('Validation','Head')],[P('Cabin Definitions'),P('Area ID, Deck, Rows From/To, Balance Arm From/Centroid/To, Index per Weight Unit.'),P('Area ID max 2 characters; Deck max 5; positive whole row numbers; From <= Centroid <= To.')],[P('Flight Deck Locations'),P('Location ID, Description, Maximum Seats, Balance Arm Centroid, Index per Weight Unit.'),P('Location ID max 3 characters; Description max 64; seats are positive whole numbers.')],[P('Cabin Crew Locations'),P('Location ID, Description, Maximum Seats, Balance Arm Centroid, Index per Weight Unit.'),P('Location ID max 3 characters; Description max 64; seats are positive whole numbers.')]]
ft=Table(fields,colWidths=[40*mm,72*mm,68*mm],repeatRows=1);ft.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),blue),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.6,line),('VALIGN',(0,0),(-1,-1),'TOP'),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,pale])]))
story += [ft,Spacer(1,4*mm),P('Status labels','H2X'),Table([[badge('CONFIGURED',green),badge('PARTIALLY CONFIGURED',amber),badge('INCOMPLETE',red)]],colWidths=[60*mm]*3,style=TableStyle([('VALIGN',(0,0),(-1,-1),'MIDDLE')]))]
def footer(canvas,doc): canvas.saveState();canvas.setStrokeColor(line);canvas.line(15*mm,10*mm,195*mm,10*mm);canvas.setFont('Helvetica',7.5);canvas.setFillColor(colors.HexColor('#61718b'));canvas.drawString(15*mm,6*mm,'Carrier Configuration - D5 Completion Rules');canvas.drawRightString(195*mm,6*mm,f'Page {doc.page}');canvas.restoreState()
doc.build(story,onFirstPage=footer,onLaterPages=footer)
print(out)
